using System;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;
namespace V15Voice {
// Explicit GDI+ measurement keeps wrapped diagnostic text and scroll height in sync.
public sealed class StudioMessageLabel:Label {
 bool measuring;
 void MeasureMessage(){if(measuring||Width<1)return;measuring=true;try{using(var bitmap=new Bitmap(1,1))using(var g=Graphics.FromImage(bitmap)){Height=Math.Max(1,(int)Math.Ceiling(g.MeasureString(Text??"",Font,Math.Max(1,Width)).Height)+3);}}finally{measuring=false;}Invalidate();}
 protected override void OnTextChanged(EventArgs e){base.OnTextChanged(e);MeasureMessage();}
 protected override void OnFontChanged(EventArgs e){base.OnFontChanged(e);MeasureMessage();}
 protected override void OnSizeChanged(EventArgs e){base.OnSizeChanged(e);MeasureMessage();}
 protected override void OnPaint(PaintEventArgs e){using(var brush=new SolidBrush(ForeColor))e.Graphics.DrawString(Text,Font,brush,new RectangleF(0,0,Math.Max(1,Width),Height));}
}
