 void WidenStudioControls(Control parent){foreach(Control c in parent.Controls){if(c is FlowLayoutPanel)WidenStudioControls(c);if(c is ComboBox){c.Font=new Font("Segoe UI",11);((ComboBox)c).IntegralHeight=false;((ComboBox)c).DropDownHeight=330;}if(c is NumericUpDown){c.Font=new Font("Segoe UI",11);c.MinimumSize=new Size(120,28);}if(c is Button){c.MinimumSize=new Size(110,38);c.Font=new Font("Segoe UI",10);}}}
 void FitStudioSettings(FlowLayoutPanel panel){int width=Math.Max(270,panel.ClientSize.Width-panel.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-8);FitStudioChildren(panel,width);}
 void FitStudioChildren(Control parent,int width){foreach(Control c in parent.Controls){if(c is FlowLayoutPanel){var flow=(FlowLayoutPanel)c;flow.AutoSizeMode=AutoSizeMode.GrowAndShrink;flow.MaximumSize=new Size(width,0);flow.MinimumSize=new Size(width,0);flow.Width=width;FitStudioChildren(c,width);}else if(c is Label){c.MaximumSize=new Size(width,0);c.Width=width;}else if(c is ComboBox||c is TextBox)c.Width=width;else if(c is TableLayoutPanel)c.Width=width;else if(c is Panel&&c.Controls.Count==1&&c.Controls[0] is Label){c.Width=width;var label=(Label)c.Controls[0];label.MaximumSize=new Size(Math.Max(220,width-34),0);label.Width=Math.Max(220,width-34);}}}
 void ResizeStudioSidebar(){if(studioVoiceCard==null||studioSidebar==null)return;int height=studioSidebar.ClientSize.Height;bool compact=height<550,tiny=height<460;int[] rows=TwoSpeakers?(compact?new[]{29,0,44,53,53,0,46,28,0}:new[]{29,50,50,55,55,35,46,28,0}):(compact?new[]{29,52,52,52,0,tiny?0:28,46,28,0}:new[]{29,55,55,59,0,44,50,28,0});int top=rows.Sum()+8;studioSidebar.RowStyles[0].Height=top;for(int i=0;i<rows.Length;i++)studioVoiceCard.RowStyles[i].Height=rows[i];var details=studioVoiceCard.GetControlFromPosition(0,5);if(details!=null)details.Visible=rows[5]>0;var db=studioVoiceCard.GetControlFromPosition(0,7);if(db!=null)db.Visible=TwoSpeakers;var second=studioVoiceCard.GetControlFromPosition(0,4);if(second!=null)second.Visible=TwoSpeakers;var language=studioVoiceCard.GetControlFromPosition(0,1);var style=studioVoiceCard.GetControlFromPosition(1,1);if(language!=null)language.Visible=rows[1]>0;if(style!=null)style.Visible=rows[1]>0;}
